_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"
_VALUES = {char: value for value, digit in enumerate(_DIGITS)
           for char in (digit, digit.upper())}


def _check_base(base):
    if not isinstance(base, int) or not 2 <= base <= 36:
        raise ValueError("base must be an integer between 2 and 36")


def to_base(number, base):
    _check_base(base)
    if number == 0:
        return "0"

    magnitude = abs(number)
    digits = []
    while magnitude:
        magnitude, remainder = divmod(magnitude, base)
        digits.append(_DIGITS[remainder])
    if number < 0:
        digits.append("-")
    return "".join(reversed(digits))


def from_base(text, base):
    _check_base(base)
    negative = text.startswith("-")
    digits = text[1:] if negative else text
    if not digits:
        raise ValueError("expected at least one digit")

    number = 0
    for char in digits:
        digit = _VALUES.get(char, base)
        if digit >= base:
            raise ValueError(f"invalid base-{base} digit: {char!r}")
        number = number * base + digit
    return -number if negative else number
